var currentLanguage = localStorage.getItem('appLanguage') || 'en';
function t(key, params = {}) {
    let text = key; // Default to key if not found
    if (translations[currentLanguage] && translations[currentLanguage][key]) {
        text = translations[currentLanguage][key];
    }
    else if (translations['en'] && translations['en'][key]) {
        text = translations['en'][key];
    }
    // Replace params
    for (const [placeholder, value] of Object.entries(params)) {
        text = text.replace(`{${placeholder}}`, value);
    }
    return text;
}
// Language metadata used to update the navbar button and lazy-load flags
const _langMetaLocal = {
    en: { flag: 'us', label: 'English' },
    es: { flag: 'es', label: 'EspaÃ±ol' },
    ar: { flag: 'sa', label: 'Ø§Ù„Ø¹Ø±Ø¨ÙŠØ©' },
    hi: { flag: 'in', label: 'à¤¹à¤¿à¤¨à¥à¤¦à¥€' },
    ja: { flag: 'jp', label: 'æ—¥æœ¬èªž' }
};

function changeLanguage(lang) {
    currentLanguage = lang;
    localStorage.setItem('appLanguage', lang);
    updateTranslations();
    document.documentElement.lang = lang; // Accessibility: Update HTML lang attribute
}
function updateTranslations() {
    // 1. Text Content
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if (!key)
            return;
        el.textContent = t(key);
    });
    // 2. Placeholders
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        if (!key)
            return;
        el.placeholder = t(key);
    });
    // 3. Dynamic Dates
    const calDate = document.getElementById('dashboard-calendar-month');
    if (calDate) {
        const now = new Date();
        const opts = { month: 'long', year: 'numeric' };
        // Map app language codes to standard locales if necessary
        let locale = currentLanguage;
        if (locale === 'ar')
            locale = 'ar-SA';
        if (locale === 'hi')
            locale = 'hi-IN';
        if (locale === 'ja')
            locale = 'ja-JP';
        if (locale === 'es')
            locale = 'es-ES';
        if (locale === 'en')
            locale = 'en-US';
        calDate.textContent = now.toLocaleDateString(locale, opts);
    }

    // Update the navbar language button (flag + text)
    if (typeof _langMetaLocal !== 'undefined') {
        const meta = _langMetaLocal[currentLanguage] || _langMetaLocal['en'];
        const langFlagImg = document.getElementById('current-lang-flag');
        const langBtnText = document.getElementById('current-lang-text');
        if (langFlagImg) {
            langFlagImg.src = `https://flagcdn.com/w40/${meta.flag}.png`;
            langFlagImg.alt = meta.label;
        }
        if (langBtnText) {
            langBtnText.textContent = meta.label;
        }
    }

    syncSettingsLanguageControl();
}

function syncSettingsLanguageControl() {
    const settingsSelect = document.getElementById('settings-language-select');
    if (settingsSelect) {
        settingsSelect.value = currentLanguage;
    }
}

function initializeSettingsLanguageControl() {
    const settingsSelect = document.getElementById('settings-language-select');
    if (settingsSelect) {
        settingsSelect.value = currentLanguage;
        settingsSelect.addEventListener('change', (e) => {
            const next = e.target && e.target.value ? e.target.value : 'en';
            changeLanguage(next);
        });
    }
}
// Initialize Language & Auth on Load
document.addEventListener('DOMContentLoaded', () => {
    (async () => {
        if (window.__cbBootInitialized)
            return;
        window.__cbBootInitialized = true;
        window.__cbInitialBootInProgress = true;
        resetHeaderIdentity();
        initializeSettingsLanguageControl();
        updateTranslations();
        const isLoggedIn = restoreAuthState();
        if (isLoggedIn) {
            await refreshPermissions();
            applyAllPermissions();
            const isPlatformOwner = isPlatformOwnerAccount();
            const userNameEl = document.getElementById('header-user-name');
            const userRoleEl = document.getElementById('header-user-role');
            const userImgEl = document.getElementById('header-user-img');
            if (userNameEl) userNameEl.textContent = isPlatformOwner ? 'Platform Owner' : (appState.name || appState.userId || 'User');
            if (userRoleEl) {
                if (isPlatformOwner) {
                    userRoleEl.textContent = 'Super Admin';
                } else {
                    userRoleEl.textContent = appState.role || 'User';
                    if (appState.schoolName && appState.schoolName !== 'Independent') userRoleEl.textContent += ` â€¢ ${appState.schoolName}`;
                }
            }
            if (userImgEl) userImgEl.src = `https://ui-avatars.com/api/?name=${encodeURIComponent(isPlatformOwner ? 'AD' : (appState.userId || 'User'))}&background=random`;
        }
        if (isLoggedIn) {
            // Phase-2: load dashboard modules for this role before rendering
            if (window.loadDashboardModules) {
                await window.loadDashboardModules(appState.role);
            }
            if (appState.role === 'Student') {
                renderStudentControls();
            }
            else if (isParentRole(appState.role)) {
                renderParentControls();
            }
            else {
                renderTeacherControls();
            }
            applyAllPermissions();
        }
        syncSettingsLanguageControl();
        // Strict Hash-Based Routing Logic
        const hash = window.location.hash.substring(1);
        const umHashes = ['user-management', 'add-user-view', 'add-user-view-v2', 'user-management-view'];
        const safeSwitch = (id) => {
            // Only switch if the element exists to avoid errors
            if (document.getElementById(id)) {
                switchView(id, false);
            }
            else {
                // Fallback for invalid hash
                if (isLoggedIn) {
                    if (appState.role === 'Student')
                        switchView('student-view', false);
                    else if (isParentRole(appState.role))
                        switchView('parent-dashboard-view', false);
                    else
                        switchView('teacher-view', false);
                }
                else {
                    switchView('landing-view', false);
                }
            }
        };
        if (hash) {
            if (umHashes.includes(hash)) {
                openUserManagement();
                window.__cbInitialBootComplete = true;
                window.__cbInitialBootInProgress = false;
                return;
            }
            const protectedViews = ['teacher-view', 'student-view', 'parent-dashboard-view', 'roles-view', 'permissions-view'];
            // If user is NOT logged in and tries to access a protected view, redirect to landing
            if (!isLoggedIn && protectedViews.some(v => hash.startsWith(v))) {
                switchView('landing-view', false);
            }
            else {
                // Otherwise (Logged in OR Public Page), try to load the specific view from hash
                safeSwitch(hash);
            }
        }
        else {
            // No hash provided
            if (isLoggedIn) {
                if (appState.role === 'Student')
                    switchView('student-view', false);
                else if (isParentRole(appState.role))
                    switchView('parent-dashboard-view', false);
                else
                    switchView('teacher-view', false);
            }
            else {
                switchView('landing-view', false);
            }
        }
        window.__cbInitialBootComplete = true;
        window.__cbInitialBootInProgress = false;
    })();
});
// --- DOM ELEMENTS & MODALS ---
const viewStack = [];
function getActiveViewId() {
    const active = document.querySelector('.view.active');
    return active ? active.id : null;
}
function openView(viewId) {
    const current = getActiveViewId();
    if (current && current !== viewId) {
        viewStack.push(current);
    }
    switchView(viewId);
}
function closeView() {
    const previous = viewStack.pop();
    if (previous) {
        switchView(previous);
    }
}
function createViewModal(viewId) {
    return {
        show: () => openView(viewId),
        hide: () => closeView()
    };
}
document.addEventListener('click', (event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const modalTrigger = target.closest('[data-bs-toggle="modal"]');
    if (modalTrigger) {
        const targetId = modalTrigger.getAttribute('data-bs-target');
        if (targetId) {
            event.preventDefault();
            openView(targetId.replace('#', ''));
        }
    }
    const dismissTrigger = target.closest('[data-bs-dismiss="modal"]');
    if (dismissTrigger) {
        event.preventDefault();
        closeView();
    }
});
