function _normalizeRolePermissionCodes(permissions) {
    if (!Array.isArray(permissions)) return [];
    return permissions
        .map((p) => {
            if (typeof p === 'string')
                return p;
            if (p && typeof p.code === 'string')
                return p.code;
            return '';
        })
        .filter(Boolean);
}

