// --- PROGRESS MARKS ENTRY ---
function computeLetterGrade(score, maxMarks) {
    if (!maxMarks || maxMarks <= 0) return '';
    const pct = (score / maxMarks) * 100;
    if (pct >= 90) return 'A+';
    if (pct >= 80) return 'A';
    if (pct >= 70) return 'B+';
    if (pct >= 60) return 'B';
    if (pct >= 50) return 'C';
    if (pct >= 40) return 'D';
    return 'F';
}

